const primary = document.querySelector(".button:not(.button--ghost)");
const label = primary?.querySelector(".button-label");

primary?.addEventListener("click", () => {
  if (primary.getAttribute("aria-busy") === "true") return;

  const previous = label?.textContent || "Publish component";
  primary.setAttribute("aria-busy", "true");
  primary.disabled = true;
  if (label) label.textContent = "Publishing…";

  window.setTimeout(() => {
    primary.removeAttribute("aria-busy");
    primary.disabled = false;
    if (label) label.textContent = previous;
  }, 1100);
