const color = document.querySelector(".token-color");
const hex = document.querySelector(".token-hex");
const swatch = document.querySelector(".swatch");
const error = document.querySelector(".token-error");
const root = document.documentElement;
const validHex = /^#[0-9a-f]{6}$/i;

function apply(value, syncHex) {
  const normalized = value.toUpperCase();

  if (color) color.value = normalized;
  if (syncHex && hex) hex.value = normalized;
  if (swatch) swatch.style.background = normalized;
  if (error) error.textContent = "";
  if (hex) hex.removeAttribute("aria-invalid");
  root.style.setProperty("--accent", normalized);
}

color?.addEventListener("input", () => apply(color.value, true));

hex?.addEventListener("input", () => {
  const value = hex.value.trim();
  if (validHex.test(value)) {
    apply(value, false);
  } else {
    hex.setAttribute("aria-invalid", "true");
    if (error) error.textContent = "Use a six-digit hex value, for example #4F46E5.";
  }
});

apply(color?.value || "#4f46e5", true);

