const plans = document.querySelectorAll(".plan");
const billing = document.querySelectorAll('input[name="billing"]');

function updatePrices() {
  const selected = document.querySelector('input[name="billing"]:checked');
  const annual = selected?.value === "annual";

  plans.forEach((plan) => {
    const price = plan.querySelector(".price");
    const monthly = plan.dataset.monthly;
    const yearly = plan.dataset.annual;
    if (!price || !monthly || !yearly) return;
    price.textContent = "$" + (annual ? yearly : monthly);
  });
}

billing.forEach((input) => input.addEventListener("change", updatePrices));
